import {FEATURES} from './features.js';import {t} from './locales.js';import {fishCanStock} from './fish-state.js';import {fishRecoveryReason} from './fish-recovery.js';import {FISH} from './fish-config.js';
/** @param {import('./engine.js').State} state @param {(type:import('./engine.js').CommandType,extra?:Partial<import('./engine.js').Command>)=>void} send @param {HTMLElement} host */
export function renderFishShop(state,send,host){const g=state.fish;if(!FEATURES.fish||!g?.visited)return;const p=g.ponds[0],box=document.createElement('section');box.id='fish-shop';const title=document.createElement('h3');title.textContent=t('fishSupplies');box.append(title);
 /** @param {string} id @param {string} label @param {import('./engine.js').CommandType} type @param {Partial<import('./engine.js').Command>} extra @param {string} [reason] */
 function button(id,label,type,extra,reason=''){const b=document.createElement('button');b.type='button';b.className='action-button';b.dataset.fishShop=id;b.textContent=label;b.disabled=!!reason;if(reason){const why=document.createElement('p');why.id='fish-shop-'+id+'-why';why.textContent=t(reason);b.title=t(reason);b.setAttribute('aria-describedby',why.id);box.append(why);}b.addEventListener('click',()=>send(type,extra));box.append(b);}
 for(const count of [1,4])button('stock'+count,t('fishRestock')+' '+count+' · '+count*FISH.fingerlingCoins+' '+t('coins'),'fish.stock',{fishPond:1,fishCount:count},!fishCanStock(p,count)?'fishCapacity':state.coins<count*FISH.fingerlingCoins?'noCoins':'');
 button('feed',t('fishBuyFeed8'),'fish.buyFeed',{fishPond:1},state.coins<FISH.feedBagCoins?'noCoins':'');button('water',t('fishBuyWater3'),'fish.buyWater',{fishPond:1},state.coins<FISH.exchangeCoins?'fishNoWater':'');
 const note=document.createElement('p');note.textContent=t('fishRecoveryHelp');box.append(note);const job=g.recovery;if(job.active){const hours=job.mode==='restock'?FISH.restockWorkHours:FISH.recoveryHours,elapsed=state.tick-job.startedTick,progress=document.createElement('p');progress.id='fish-work-progress';progress.textContent=t(job.mode==='restock'?'fishRestockWork':'fishCareWork')+' · '+Math.min(elapsed,hours)+' / '+hours+' h';box.append(progress);button('claim',t('fishClaimWork'),'fish.claimRecovery',{fishPond:1},elapsed<hours?'fishJobWorking':'');}else button('work',t('fishStartWork'),'fish.startRecovery',{fishPond:1},fishRecoveryReason(state));if(job.advanceCoins){const debt=document.createElement('p');debt.textContent=t('fishAdvanceNote')+' '+job.advanceCoins+' '+t('coins');box.append(debt);}host.append(box);}
